function loopsConverted = convertLoopToRooftopIndices(loops, countX, countY)
% convertLoopToRooftopIndices: Returns a loop basis but now in terms of the
%   rooftop indices.
%
%   Inputs:
%       loops: 4xN matrix generated by the generateLoops function
%       countX: Positive integer specifying the number of patches in the x direction.
%       countY: Positive integer specifying the number of patches in the y direction.
%
%   Output:
%       loopsConverted: 4xN matrix describing the loop basis functions in terms of
%           rooftop indices.

    numBasisX = (countX - 1) * countY;
    offset = numBasisX - countX; 

    % NOTE: The way that the loop basis functions are generated we
    % can avoid using the loopBasis for the x-dir rooftops
    loopsConverted = [
        1:size(loops, 2);
        loops(2, :) + numBasisX;
        countX:numBasisX;
        loops(4, :) + offset
    ];
end
